"""
Market data via yfinance 1.x + curl_cffi browser impersonation.

Uses a persistent Chrome-impersonating session so Yahoo Finance
doesn't block requests as bot traffic (the root cause of 429 / empty crumb).
"""

import asyncio
import random
import time as _time
from concurrent.futures import ThreadPoolExecutor
from typing import Optional

import pandas as pd
import pytz
import yfinance as yf
from curl_cffi import requests as curl_requests

_executor = ThreadPoolExecutor(max_workers=4)
_yf_lock = asyncio.Lock()  # serialise per-ticker calls that aren't batched
_YF_DELAY = 0.8  # seconds between serialised calls

# One long-lived session that looks like Chrome — avoids Yahoo 429s
_session = curl_requests.Session(impersonate="chrome110")

# ── yfinance Global Circuit Breaker ─────────────────────────────────────────
# When yfinance returns a 429, skip all yfinance calls for 15 minutes so the
# IP rate-limit bucket resets naturally instead of compounding the ban.
_yf_backoff_until: float = 0.0  # epoch timestamp; 0 = not in backoff
_YF_BACKOFF_SECS = 900  # 15 minutes


from mutmut.mutation.trampoline import wrap_in_trampoline as _mutmut_mutated, MutantDict
mutants_x__yf_is_blocked__mutmut: MutantDict = {}  # type: ignore


@_mutmut_mutated(mutants_x__yf_is_blocked__mutmut)
def _yf_is_blocked() -> bool:
    return _time.time() < _yf_backoff_until


def x__yf_is_blocked__mutmut_orig() -> bool:
    return _time.time() < _yf_backoff_until


def x__yf_is_blocked__mutmut_1() -> bool:
    return _time.time() <= _yf_backoff_until

mutants_x__yf_is_blocked__mutmut['_mutmut_orig'] = x__yf_is_blocked__mutmut_orig # type: ignore # mutmut generated
mutants_x__yf_is_blocked__mutmut['x__yf_is_blocked__mutmut_1'] = x__yf_is_blocked__mutmut_1 # type: ignore # mutmut generated
mutants_x__yf_trip_breaker__mutmut: MutantDict = {}  # type: ignore


@_mutmut_mutated(mutants_x__yf_trip_breaker__mutmut)
def _yf_trip_breaker():
    global _yf_backoff_until
    _yf_backoff_until = _time.time() + _YF_BACKOFF_SECS


def x__yf_trip_breaker__mutmut_orig():
    global _yf_backoff_until
    _yf_backoff_until = _time.time() + _YF_BACKOFF_SECS


def x__yf_trip_breaker__mutmut_1():
    global _yf_backoff_until
    _yf_backoff_until = None


def x__yf_trip_breaker__mutmut_2():
    global _yf_backoff_until
    _yf_backoff_until = _time.time() - _YF_BACKOFF_SECS

mutants_x__yf_trip_breaker__mutmut['_mutmut_orig'] = x__yf_trip_breaker__mutmut_orig # type: ignore # mutmut generated
mutants_x__yf_trip_breaker__mutmut['x__yf_trip_breaker__mutmut_1'] = x__yf_trip_breaker__mutmut_1 # type: ignore # mutmut generated
mutants_x__yf_trip_breaker__mutmut['x__yf_trip_breaker__mutmut_2'] = x__yf_trip_breaker__mutmut_2 # type: ignore # mutmut generated


# ── Polygon OHLCV Shared Cache ───────────────────────────────────────────────
# Redis-backed with in-memory fallback.
# Redis (when available) enables cache sharing across Uvicorn workers so a
# restart or second worker doesn't re-download the same Polygon bars within
# the same 15-min scan cycle.  Falls back to an in-process dict if Redis is
# not reachable — behaviour is identical from the caller's perspective.
#
# STAMPEDE PROTECTION: _fetch_locks ensures only one concurrent coroutine
# fetches a given (ticker, period, interval) key from the upstream API.
# Others wait on the lock and hit the cache when they acquire it, avoiding
# the N-worker × M-ticker Polygon rate-limit burst that occurs when Redis
# goes dark and every worker independently triggers a full re-fetch.
_OHLCV_TTL = 900  # 15 minutes
_OHLCV_MAX_ENTRIES = 500  # in-memory fallback cap

import logging as _log_mod
import os as _os
import threading as _threading

_cache_log = _log_mod.getLogger("signal.trade.cache")

# Per-key fetch locks (asyncio-friendly via threading.Lock in executor context).
# Capped at _FETCH_LOCKS_MAX to prevent unbounded growth from arbitrary API callers.
# Eviction drops the oldest half when the cap is hit (LRU-approximation without
# a full OrderedDict to keep the hot-path overhead minimal).
_fetch_locks: dict[tuple, _threading.Lock] = {}
_fetch_locks_mu = _threading.Lock()
_FETCH_LOCKS_MAX = 2_000
mutants_x__get_fetch_lock__mutmut: MutantDict = {}  # type: ignore


@_mutmut_mutated(mutants_x__get_fetch_lock__mutmut)
def _get_fetch_lock(key: tuple) -> _threading.Lock:
    with _fetch_locks_mu:
        if key not in _fetch_locks:
            if len(_fetch_locks) >= _FETCH_LOCKS_MAX:
                # Evict oldest half — keys() is insertion-ordered in Python 3.7+
                to_remove = list(_fetch_locks.keys())[: _FETCH_LOCKS_MAX // 2]
                for k in to_remove:
                    del _fetch_locks[k]
            _fetch_locks[key] = _threading.Lock()
        return _fetch_locks[key]


