# ── Attempt Redis connection at import time ───────────────────────────────────
_redis_client = None
try:
    import redis as _redis_lib

    _redis_url = _os.getenv("REDIS_URL", "redis://localhost:6379/0")
    _redis_client = _redis_lib.Redis.from_url(
        _redis_url, socket_connect_timeout=1, socket_timeout=1, decode_responses=False
    )
    _redis_client.ping()
    _cache_log.info(f"[cache] Redis connected — OHLCV cache shared across workers ({_redis_url})")
except Exception as _redis_err:
    _redis_client = None
    _cache_log.debug(f"[cache] Redis unavailable ({_redis_err!r}) — using in-process fallback")

# In-memory fallback (used when Redis is not reachable)
_ohlcv_cache: dict[tuple, dict] = {}
mutants_x__ohlcv_cache_get__mutmut: MutantDict = {}  # type: ignore


@_mutmut_mutated(mutants_x__ohlcv_cache_get__mutmut)
def _ohlcv_cache_get(key: tuple) -> "Optional[pd.DataFrame]":
    """Return a cached DataFrame if present and not expired, else None."""
    import pickle as _pickle
    from services.provider_telemetry import record_cache_hit, record_cache_miss, current_cycle_id

    cycle_id = current_cycle_id.get()

    if _redis_client is not None:
        try:
            raw = _redis_client.get(f"ohlcv:{':'.join(str(k) for k in key)}")
            if raw:
                record_cache_hit(cycle_id, "yfinance")
                return _pickle.loads(raw)
            # Redis is up and confirmed a miss — don't fall through to stale in-memory.
            record_cache_miss(cycle_id, "yfinance")
            return None
        except Exception:
            # Redis went down mid-session; fall through to in-memory fallback so the
            # circuit breaker trip doesn't also blank the local cache.
            pass
    # In-memory fallback (also used when Redis is down mid-session)
    entry = _ohlcv_cache.get(key)
    if entry and _time.time() - entry["ts"] < _OHLCV_TTL:
        record_cache_hit(cycle_id, "yfinance")
        return entry["df"]
    record_cache_miss(cycle_id, "yfinance")
    return None


