@_mutmut_mutated(mutants_x__fetch_quotes_batch__mutmut)
def _fetch_quotes_batch(tickers: list[str]) -> list[dict]:
    try:
        raw = _retry(
            yf.download,
            tickers,
            period="2d",
            interval="1d",  # 2d is enough for current + prev close
            auto_adjust=True,
            progress=False,
            threads=False,
            session=_session,
        )
        if raw is None or raw.empty:
            return []

        out = []
        if len(tickers) == 1:
            t = tickers[0]
            close = raw["Close"]
            if len(close) >= 2:
                price = float(close.iloc[-1])
                prev = float(close.iloc[-2])
                out.append({"t": t, "p": round(price, 2), "c": round((price - prev) / prev * 100, 2)})
        else:
            close = raw["Close"]
            for t in tickers:
                try:
                    s = close[t].dropna()
                    if len(s) < 2:
                        continue
                    price = float(s.iloc[-1])
                    prev = float(s.iloc[-2])
                    out.append({"t": t, "p": round(price, 2), "c": round((price - prev) / prev * 100, 2)})
                except (KeyError, TypeError):
                    pass
        return out
    except Exception as e:
        print(f"[market_data] batch quotes error: {e}")
        return []


